SELECT t1.id, t1.user_id, t1.upload_time, t1.direction, t1.lng, t1.lat, t1.address, t1.height, t1.speed, t1.tenant, t1.deleted, t1.create_by, t1.creator_id, t1.creator_type, t1.create_time, t1.update_by, t1.updater_id, t1.updater_type, t1.update_time FROM user_gps_history t1 JOIN ( SELECT user_id, MAX(upload_time) AS upload_time FROM user_gps_history where user_id in
#{userId}
GROUP BY user_id ) t2 ON t1.user_id = t2.user_id AND t1.upload_time = t2.upload_time
